import React, { useEffect, useState } from 'react';
import {
    Box, Button, Dialog, DialogActions, DialogContent, DialogTitle,
    IconButton, MenuItem, Select, Table, TableBody, TableCell, TableHead,
    TableRow, TextField, Checkbox, Typography, FormControl,
    OutlinedInput, Chip
} from '@mui/material';
import DeleteIcon from '@mui/icons-material/Delete';
import ArrowUpwardIcon from '@mui/icons-material/ArrowUpward';
import ArrowDownwardIcon from '@mui/icons-material/ArrowDownward';
import SaveIcon from '@mui/icons-material/Save';

// Import API functions
import { fetchForms, updateFormData } from '../api/formApi';
// Import validation options
import { validationOptions } from '../utils/validationOptions';
// Import control types
import { controlTypes } from '../utils/controlTypes';

const ManageDynamicForm = () => {
    const [forms, setForms] = useState([]);
    const [selectedFormId, setSelectedFormId] = useState('');
    const [formFields, setFormFields] = useState([]);
    const [openConfirm, setOpenConfirm] = useState(false);
    const [formDescription, setFormDescription] = useState('');
    const [formName, setFormName] = useState(''); // Add formName state

    useEffect(() => {
        fetchForms()
            .then(data => {
                setForms(data);
            })
            .catch(error => {
                console.error('Error fetching forms:', error);
                alert('Failed to load forms.');
            });
    }, []);

    // const handleFormSelect = (event) => {
    //     const formId = event.target.value;
    //     setSelectedFormId(formId);
    //     const selectedFormObject = forms.find(f => f.id === parseInt(formId, 10));
    //     if (selectedFormObject?.form_data) {
    //         setFormFields([...selectedFormObject.form_data.fields]);
    //         setFormDescription(selectedFormObject.form_data.formDescription);
    //         setFormName(selectedFormObject.form_data.formName);
    //     } else {
    //         setFormFields([]);
    //         setFormDescription('');
    //         setFormName('');
    //     }
    // };

    // const handleFieldChange = (index, field, value) => {
    //     const updatedFields = [...formFields];
    //     updatedFields[index][field] = value;

    //     if (field === 'optionsCount') {
    //         const count = parseInt(value) || 0;
    //         updatedFields[index].options = Array(count).fill('');
    //     }

    //     setFormFields(updatedFields);
    // };

    // const handleOptionChange = (fieldIndex, optionIndex, value) => {
    //     const updatedFields = [...formFields];
    //     if (!updatedFields[fieldIndex].options) {
    //         updatedFields[fieldIndex].options = [];
    //     }
    //     updatedFields[fieldIndex].options[optionIndex] = value;
    //     setFormFields(updatedFields);
    // };

    // const handleDeleteField = (index) => {
    //     const updatedFields = [...formFields];
    //     updatedFields.splice(index, 1);
    //     setFormFields(updatedFields);
    // };

    const handleFieldChange = (index, field, value) => {
        const updatedFields = formFields.map((item, idx) =>
            idx === index ? { ...item, [field]: value } : item
        );
        setFormFields(updatedFields);
        console.log('formFields after handleFieldChange:', updatedFields);
    };

    const handleOptionChange = (fieldIndex, optionIndex, value) => {
        const updatedFields = formFields.map((item, idx) =>
            idx === fieldIndex ? {
                ...item,
                options: item.options.map((opt, optIdx) =>
                    optIdx === optionIndex ? value : opt
                )
            } : item
        );
        setFormFields(updatedFields);
        console.log('formFields after handleOptionChange:', updatedFields);
    };

    const handleDeleteField = (index) => {
        const updatedFields = formFields.filter((_, idx) => idx !== index);
        setFormFields(updatedFields);
        console.log('formFields after handleDeleteField:', updatedFields);
    };

    const handleAddField = () => {
        const newField = {
            id: Date.now(),
            label: '',
            controlType: 'text',
            placeholder: '',
            errorMessage: '',
            minLength: '',
            maxLength: '',
            optionsCount: 0,
            options: [],
            validations: [],
            available: true,
        };
        setFormFields(prevFields => [...prevFields, newField]);
        console.log('formFields after handleAddField:', [...formFields, newField]);
    };

    const handleFormSelect = (event) => {
        const formId = event.target.value;
        setSelectedFormId(formId);
        const selectedFormObject = forms.find(f => f.id === parseInt(formId, 10));
        if (selectedFormObject?.form_data) {
            setFormFields([...selectedFormObject.form_data.fields]);
            setFormDescription(selectedFormObject.form_data.formDescription);
            setFormName(selectedFormObject.form_data.formName);
            console.log('Selected form data:', selectedFormObject?.form_data);
            console.log('formFields after handleFormSelect:', [...selectedFormObject.form_data.fields]);
        } else {
            setFormFields([]);
            setFormDescription('');
            setFormName('');
            console.log('No form data found for selected form.');
            console.log('formFields after handleFormSelect (empty):', []);
        }
    };

    const handleMoveField = (index, direction) => {
        const updatedFields = [...formFields];
        const targetIndex = direction === 'up' ? index - 1 : index + 1;

        if (targetIndex >= 0 && targetIndex < updatedFields.length) {
            const temp = updatedFields[index];
            updatedFields[index] = updatedFields[targetIndex];
            updatedFields[targetIndex] = temp;
            setFormFields(updatedFields);
        }
    };

    const handleSave = async () => {
        if (!selectedFormId) {
            alert('Please select a form to save.');
            return;
        }

        const updatedFormDetails = {
            form_data: {
                formName: formName,
                formDescription: formDescription,
                fields: formFields,
            },
        };

        try {
            const data = await updateFormData(selectedFormId, updatedFormDetails);
            alert('Form updated successfully!');
            console.log('Form updated:', data);

            // Refetch forms and *then* try to reset the selected form
            fetchForms()
                .then(updatedFormsData => {
                    setForms(updatedFormsData);
                    // Keep the selected form in the dropdown after update
                    // Find the updated form in the new array
                    const updatedSelectedForm = updatedFormsData.find(
                        (form) => form.id === parseInt(selectedFormId, 10)
                    );
                    // If the updated form is found, we can optionally update other states
                    // if needed, but the selectedFormId should already be correct.
                    if (updatedSelectedForm?.form_data) {
                        setFormName(updatedSelectedForm.form_data.formName);
                        setFormDescription(updatedSelectedForm.form_data.formDescription);
                        setFormFields([...updatedSelectedForm.form_data.fields]);
                    }
                })
                .catch(error => {
                    console.error('Error refetching forms after update:', error);
                    alert('Failed to refresh form list.');
                });

            setOpenConfirm(false);
        } catch (error) {
            alert('Failed to update form.');
            console.error('Error updating form:', error);
        }
    };

    // const handleAddField = () => {
    //     const newField = {
    //         id: Date.now(), // Add a unique ID for new fields
    //         label: '',
    //         controlType: 'text',
    //         placeholder: '',
    //         errorMessage: '',
    //         minLength: '',
    //         maxLength: '',
    //         optionsCount: 0,
    //         options: [],
    //         validations: [],
    //         available: true,
    //     };
    //     setFormFields(prevFields => [...prevFields, newField]);
    // };

    // Find the name of the currently selected form for display
    const selectedFormName = forms.find(form => form.id === parseInt(selectedFormId, 10))?.form_data?.formName || '';

    return (
        <Box p={3}>
            <Typography variant="h6" gutterBottom>Manage Dynamic Form</Typography>
            <Select
                displayEmpty
                value={selectedFormId || ''}
                onChange={handleFormSelect}
                fullWidth
                size="small"
            >
                <MenuItem value="" disabled>Select a form</MenuItem>
                {forms.map((form) => (
                    <MenuItem key={form.id} value={form.id}>
                        {form.form_data?.formName}
                    </MenuItem>
                ))}
            </Select>

            {selectedFormId && (
                <Box mt={3}>
                    <Box display="flex" justifyContent="flex-end" mb={1}>
                        <Button variant="outlined" color="primary" onClick={handleAddField}>
                            Add Field
                        </Button>
                    </Box>
                    <Table>
                        <TableHead>
                            <TableRow>
                                <TableCell colSpan={9}>
                                    <Typography variant="h6">Form Name: {selectedFormName}</Typography>
                                </TableCell>
                            </TableRow>
                            <TableRow>
                                <TableCell colSpan={9}>
                                    <TextField
                                        label="Form Description"
                                        fullWidth
                                        value={formDescription}
                                        onChange={(e) => setFormDescription(e.target.value)}
                                    />
                                </TableCell>
                            </TableRow>
                            <TableRow>
                                <TableCell>Label</TableCell>
                                <TableCell>Control Type</TableCell>
                                <TableCell>Validations</TableCell>
                                <TableCell>Placeholder</TableCell>
                                <TableCell>Error Message</TableCell>
                                <TableCell>Helper Text</TableCell>
                                <TableCell>Min Length</TableCell>
                                <TableCell>Max Length</TableCell>
                                <TableCell>Options</TableCell>
                                <TableCell>Actions</TableCell>
                            </TableRow>
                        </TableHead>
                        <TableBody>
                            {formFields.map((field, index) => (
                                <TableRow key={field.id || index}> {/* Use field.id if available, otherwise index */}
                                    <TableCell>
                                        <TextField
                                            value={field.label}
                                            onChange={(e) => handleFieldChange(index, 'label', e.target.value)}
                                            size="small"
                                        />
                                    </TableCell>
                                    <TableCell>
                                        <Select
                                            value={field.controlType}
                                            onChange={(e) => handleFieldChange(index, 'controlType', e.target.value)}
                                            size="small"
                                        >
                                            {controlTypes.map((type) => (
                                                <MenuItem key={type.value} value={type.value}>
                                                    {type.label}
                                                </MenuItem>
                                            ))}
                                        </Select>
                                    </TableCell>
                                    <TableCell>
                                        <FormControl fullWidth size="small">
                                            <Select
                                                multiple
                                                value={field.validations || []}
                                                onChange={(e) => handleFieldChange(index, 'validations', e.target.value)}
                                                input={<OutlinedInput />}
                                                renderValue={(selected) => (
                                                    <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5 }}>
                                                        {selected.map((val) => {
                                                            const label = validationOptions.find(v => v.value === val)?.label || val;
                                                            return <Chip key={val} label={label} />;
                                                        })}
                                                    </Box>
                                                )}
                                            >
                                                {validationOptions.map((option) => (
                                                    <MenuItem key={option.value} value={option.value}>
                                                        <Checkbox checked={field.validations?.includes(option.value)} />
                                                        {option.label}
                                                    </MenuItem>
                                                ))}
                                            </Select>
                                        </FormControl>
                                    </TableCell>
                                    <TableCell>
                                        <TextField
                                            value={field.placeholder}
                                            onChange={(e) => handleFieldChange(index, 'placeholder', e.target.value)}
                                            size="small"
                                        />
                                    </TableCell>
                                    <TableCell>
                                        <TextField
                                            value={field.errorMessage}
                                            onChange={(e) => handleFieldChange(index, 'errorMessage', e.target.value)}
                                            size="small"
                                        />
                                    </TableCell>
                                    <TableCell>
                                        <TextField
                                            value={field.helperText || ''}
                                            onChange={(e) => handleFieldChange(index, 'helperText', e.target.value)}
                                            size="small"
                                        />
                                    </TableCell>
                                    <TableCell>
                                        {['text', 'number', 'password'].includes(field.controlType) && (
                                            <TextField
                                                type="number"
                                                value={field.minLength || ''}
                                                onChange={(e) => handleFieldChange(index, 'minLength', e.target.value)}
                                                size="small"
                                            />
                                        )}
                                    </TableCell>
                                    <TableCell>
                                        {['text', 'number', 'password'].includes(field.controlType) && (
                                            <TextField
                                                type="number"
                                                value={field.maxLength || ''}
                                                onChange={(e) => handleFieldChange(index, 'maxLength', e.target.value)}
                                                size="small"
                                            />
                                        )}
                                    </TableCell>
                                    <TableCell>
                                        {['radio', 'checkbox'].includes(field.controlType) && (
                                            <Box>
                                                <TextField
                                                    label="Options Count"
                                                    type="number"
                                                    value={field.optionsCount || ''}
                                                    onChange={(e) => handleFieldChange(index, 'optionsCount', e.target.value)}
                                                    size="small"
                                                />
                                                {field.options?.map((option, optIndex) => (
                                                    <TextField
                                                        key={optIndex}
                                                        value={option}
                                                        onChange={(e) => handleOptionChange(index, optIndex, e.target.value)}
                                                        placeholder={`Option ${optIndex + 1}`}
                                                        size="small"
                                                        style={{ marginTop: 4 }}
                                                    />
                                                ))}
                                            </Box>
                                        )}
                                    </TableCell>
                                    <TableCell>
                                        <IconButton onClick={() => handleMoveField(index, 'up')}>
                                            <ArrowUpwardIcon />
                                        </IconButton>
                                        <IconButton onClick={() => handleMoveField(index, 'down')}>
                                            <ArrowDownwardIcon />
                                        </IconButton>
                                        <IconButton color="error" onClick={() => handleDeleteField(index)}>
                                            <DeleteIcon />
                                        </IconButton>
                                    </TableCell>
                                </TableRow>
                            ))}
                        </TableBody>
                    </Table>
                    <Button
                        variant="contained"
                        color="primary"
                        startIcon={<SaveIcon />}
                        onClick={() => setOpenConfirm(true)}
                        style={{ marginTop: 16 }}
                    >
                        Save Form
                    </Button>
                </Box>
            )}

            {/* Confirmation Dialog */}
            <Dialog open={openConfirm} onClose={() => setOpenConfirm(false)}>
                <DialogTitle>Confirm Save</DialogTitle>
                <DialogContent>
                    Are you sure you want to save changes to this form?
                </DialogContent>
                <DialogActions>
                    <Button onClick={() => setOpenConfirm(false)} color="secondary">Cancel</Button>
                    <Button onClick={handleSave} color="primary">Yes, Save</Button>
                </DialogActions>
            </Dialog>
        </Box>
    );
};

export default ManageDynamicForm;
